/// The wire hyperlink kind byte. (Zig: file-local `enum(u8)`.)
#[repr(u8)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Kind {
    Implicit = 1,
    Explicit = 2,
}

impl Kind {
    /// `std.enums.fromInt(Kind, raw)`
    fn from_int(raw: u8) -> Option<Kind> {
        Some(match raw {
            1 => Kind::Implicit,
            2 => Kind::Explicit,
            _ => return None,
        })
    }
}

/// Errors possible while encoding one hyperlink entry.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EncodeError {
    // std.Io.Writer.Error
    WriteFailed,

    /// A native hyperlink URI must contain at least one byte.
    InvalidUri,

    /// A native explicit hyperlink ID must contain at least one byte.
    InvalidExplicitId,

    /// A string does not fit the version 1 length field.
    StringTooLong,
}

impl From<io::WriteFailed> for EncodeError {
    fn from(_: io::WriteFailed) -> EncodeError {
        EncodeError::WriteFailed
    }
}

/// Errors possible while decoding one allocator-owned hyperlink entry.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DecodeError {
    // std.Io.Reader.Error
    ReadFailed,
    EndOfStream,
    // Allocator.Error
    OutOfMemory,

    /// The hyperlink kind is not defined by snapshot version 1.
    InvalidKind,

    /// A native hyperlink URI must contain at least one byte.
    InvalidUri,

    /// A native explicit hyperlink ID must contain at least one byte.
    InvalidExplicitId,
}

impl From<io::ReadError> for DecodeError {
    fn from(err: io::ReadError) -> DecodeError {
        match err {
            io::ReadError::ReadFailed => DecodeError::ReadFailed,
            io::ReadError::EndOfStream => DecodeError::EndOfStream,
        }
    }
}

/// Errors possible while decoding directly into a native page.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DecodePageError {
    // std.Io.Reader.Error
    ReadFailed,
    EndOfStream,

    /// The hyperlink kind is not defined by snapshot version 1.
    InvalidKind,
}

impl From<io::ReadError> for DecodePageError {
    fn from(err: io::ReadError) -> DecodePageError {
        match err {
            io::ReadError::ReadFailed => DecodePageError::ReadFailed,
            io::ReadError::EndOfStream => DecodePageError::EndOfStream,
        }
    }
}

/// Encode one hyperlink entry.
pub fn encode(
    value: &terminal_hyperlink::Hyperlink,
    writer: &mut dyn io::Writer,
) -> Result<(), EncodeError> {
    // Validate the complete value before writing any part of this variable-
    // length entry. This keeps callers able to roll back at entry boundaries.
    if value.uri.is_empty() {
        return Err(EncodeError::InvalidUri);
    }
    if u32::try_from(value.uri.len()).is_err() {
        return Err(EncodeError::StringTooLong);
    }
    if let terminal_hyperlink::HyperlinkId::Explicit(id) = &value.id {
        if id.is_empty() {
            return Err(EncodeError::InvalidExplicitId);
        }
        if u32::try_from(id.len()).is_err() {
            return Err(EncodeError::StringTooLong);
        }
    }

    match &value.id {
        terminal_hyperlink::HyperlinkId::Implicit(id) => {
            writer.write_byte(Kind::Implicit as u8)?;
            io::write_int::<u32>(writer, *id)?;
            io::write_int::<u32>(writer, value.uri.len() as u32)?;
            writer.write_all(&value.uri)?;
        }
        terminal_hyperlink::HyperlinkId::Explicit(id) => {
            writer.write_byte(Kind::Explicit as u8)?;
            io::write_int::<u32>(writer, id.len() as u32)?;
            writer.write_all(id)?;
            io::write_int::<u32>(writer, value.uri.len() as u32)?;
            writer.write_all(&value.uri)?;
        }
    }
    Ok(())
}

/// `alloc.alloc(u8, len)` — a fallible zeroed byte buffer, with the crate's
/// tripwire seam standing in for the reference tests' FailingAllocator.
fn decode_alloc(len: usize) -> Result<Vec<u8>, DecodeError> {
    #[cfg(test)]
    super::tw::check(super::tw::SnapshotFp::Alloc).map_err(|_| DecodeError::OutOfMemory)?;

    let mut bytes: Vec<u8> = Vec::new();
    bytes
        .try_reserve_exact(len)
        .map_err(|_| DecodeError::OutOfMemory)?;
    bytes.resize(len, 0);
    Ok(bytes)
}

/// Decode one allocator-owned hyperlink entry.
///
/// The caller owns the returned value and must call `Hyperlink.deinit`.
pub fn decode(
    reader: &mut dyn io::Reader,
) -> Result<terminal_hyperlink::Hyperlink, DecodeError> {
    let kind_raw = reader.take_byte()?;
    let kind = Kind::from_int(kind_raw).ok_or(DecodeError::InvalidKind)?;

    match kind {
        Kind::Implicit => {
            let id = io::read_int::<u32>(reader)?;
            let uri_len = io::read_int::<u32>(reader)? as usize;
            if uri_len == 0 {
                return Err(DecodeError::InvalidUri);
            }

            let mut uri = decode_alloc(uri_len)?;
            // errdefer alloc.free(uri); — the Vec drops on the error path.
            reader.read_slice_all(&mut uri)?;

            Ok(terminal_hyperlink::Hyperlink {
                id: terminal_hyperlink::HyperlinkId::Implicit(id),
                uri,
            })
        }

        Kind::Explicit => {
            let id_len = io::read_int::<u32>(reader)? as usize;
            if id_len == 0 {
                return Err(DecodeError::InvalidExplicitId);
            }

            let mut id = decode_alloc(id_len)?;
            // errdefer alloc.free(id);
            reader.read_slice_all(&mut id)?;

            let uri_len = io::read_int::<u32>(reader)? as usize;
            if uri_len == 0 {
                return Err(DecodeError::InvalidUri);
            }

            let mut uri = decode_alloc(uri_len)?;
            // errdefer alloc.free(uri);
            reader.read_slice_all(&mut uri)?;

            Ok(terminal_hyperlink::Hyperlink {
                id: terminal_hyperlink::HyperlinkId::Explicit(id),
                uri,
            })
        }
    }
}

/// The `decode_page_string` error set.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum DecodePageStringError {
    ReadFailed,
    EndOfStream,
    StringsOutOfMemory,
}

impl From<io::ReadError> for DecodePageStringError {
    fn from(err: io::ReadError) -> DecodePageStringError {
        match err {
            io::ReadError::ReadFailed => DecodePageStringError::ReadFailed,
            io::ReadError::EndOfStream => DecodePageStringError::EndOfStream,
        }
    }
}

impl From<DecodePageStringError> for DecodePageError {
    /// Only the reader members convert; `StringsOutOfMemory` is always
    /// handled at the call sites (it degrades to native ID zero).
    fn from(err: DecodePageStringError) -> DecodePageError {
        match err {
            DecodePageStringError::ReadFailed => DecodePageError::ReadFailed,
            DecodePageStringError::EndOfStream => DecodePageError::EndOfStream,
            DecodePageStringError::StringsOutOfMemory => {
                unreachable!("StringsOutOfMemory is handled at every call site")
            }
        }
    }
}

/// Decode one hyperlink directly into page-owned storage.
///
/// Explicit ID and URI bytes are read into the page string allocator and the
/// completed entry is inserted into the page hyperlink set. The returned ID is
/// the native ID assigned by the destination page. Zero is returned when the
/// encoded value cannot be represented within the destination page, including
/// empty strings and insufficient advertised capacity.
pub fn decode_page(
    page: &mut Page,
    reader: &mut dyn io::Reader,
) -> Result<terminal_hyperlink::Id, DecodePageError> {
    let kind_raw = reader.take_byte()?;
    let kind = Kind::from_int(kind_raw).ok_or(DecodePageError::InvalidKind)?;

    let entry: terminal_hyperlink::PageEntry = match kind {
        Kind::Implicit => {
            let id = io::read_int::<u32>(reader)?;
            let uri_len = io::read_int::<u32>(reader)? as usize;
            if uri_len == 0 {
                return Ok(0);
            }

            let uri = match decode_page_string(page, reader, uri_len) {
                Ok(uri) => uri,
                Err(DecodePageStringError::StringsOutOfMemory) => {
                    reader.discard_all(uri_len)?;
                    return Ok(0);
                }
                Err(read_err) => return Err(read_err.into()),
            };

            terminal_hyperlink::PageEntry {
                id: terminal_hyperlink::PageEntryId::Implicit(id),
                uri,
            }
        }

        Kind::Explicit => {
            let id_len = io::read_int::<u32>(reader)? as usize;
            if id_len == 0 {
                let uri_len = io::read_int::<u32>(reader)? as usize;
                reader.discard_all(uri_len)?;
                return Ok(0);
            }

            let id = match decode_page_string(page, reader, id_len) {
                Ok(id) => id,
                Err(DecodePageStringError::StringsOutOfMemory) => {
                    reader.discard_all(id_len)?;
                    let uri_len = io::read_int::<u32>(reader)? as usize;
                    reader.discard_all(uri_len)?;
                    return Ok(0);
                }
                Err(read_err) => return Err(read_err.into()),
            };
            // errdefer page.string_alloc.free(page.memory, id.slice(page.memory));
            // (Rust: every error/degrade path below frees `id` explicitly.)

            let uri_len = match io::read_int::<u32>(reader) {
                Ok(v) => v as usize,
                Err(err) => {
                    free_page_string(page, id);
                    return Err(err.into());
                }
            };
            if uri_len == 0 {
                free_page_string(page, id);
                return Ok(0);
            }

            let uri = match decode_page_string(page, reader, uri_len) {
                Ok(uri) => uri,
                Err(DecodePageStringError::StringsOutOfMemory) => {
                    if let Err(err) = reader.discard_all(uri_len) {
                        free_page_string(page, id);
                        return Err(err.into());
                    }
                    free_page_string(page, id);
                    return Ok(0);
                }
                Err(read_err) => {
                    free_page_string(page, id);
                    return Err(read_err.into());
                }
            };

            terminal_hyperlink::PageEntry {
                id: terminal_hyperlink::PageEntryId::Explicit(id),
                uri,
            }
        }
    };

    let page_ptr: *mut Page = page;
    let base = page.memory_ptr();
    // return page.hyperlink_set.addContext(page.memory, entry, .{ .page = page })
    // (the crate's RefCountedSet stores the per-call context; see the
    // hyperlink.rs PORT NOTE on `addContext`.)
    page.hyperlink_set.context.set_page(page_ptr);
    page.hyperlink_set.context.set_src_page(None);
    // SAFETY: `base` is the true base of the page's backing mapping and the
    // context page pointer was set immediately above (the insert_hyperlink
    // pattern).
    match unsafe { page.hyperlink_set.add(base, entry) } {
        Ok(id) => Ok(id),
        Err(_) => {
            // The entry was fully consumed, so capacity failure only loses this
            // optional hyperlink. Free its strings and let cells restore unlinked.
            // SAFETY: `page_ptr` is the live destination page; `entry` was
            // never inserted, so its strings are exclusively ours to free.
            unsafe { entry.free(page_ptr) };
            Ok(0)
        }
    }
}

fn decode_page_string(
    page: &mut Page,
    reader: &mut dyn io::Reader,
    len: usize,
) -> Result<OffsetSlice<u8>, DecodePageStringError> {
    debug_assert!(len > 0);
    let page_ptr: *mut Page = page;

    // Allocate space for the string and read directly into it.
    // SAFETY: `page_ptr` points at a live Page; the helper projects to the
    // `string_alloc` field only (the crate's narrow-scope raw-page pattern).
    let value: &mut [u8] = match unsafe { Page::string_alloc_alloc(page_ptr, len) } {
        Ok(v) => v,
        Err(_) => return Err(DecodePageStringError::StringsOutOfMemory),
    };
    // errdefer page.string_alloc.free(page.memory, value);
    if let Err(err) = reader.read_slice_all(value) {
        // SAFETY: as above; releases the exact allocation on the error path.
        unsafe { Page::string_alloc_free(page_ptr, value) };
        return Err(err.into());
    }

    let base = page.memory_ptr();
    Ok(OffsetSlice::new(
        // SAFETY: `&value[0]` points into the page mapping based at `base`.
        unsafe { get_offset::<u8, _>(base, &value[0]) },
        value.len(),
    ))
}

/// `page.string_alloc.free(page.memory, slice.slice(page.memory))` — the
/// explicit form of the reference's errdefer on a decoded page string.
fn free_page_string(page: &mut Page, slice: OffsetSlice<u8>) {
    let page_ptr: *mut Page = page;
    let base = page.memory_ptr();
    // SAFETY: `slice` was produced by `decode_page_string` against this same
    // page and has not been freed; the helper projects to `string_alloc` only.
    unsafe {
        let s = slice.slice(base);
        Page::string_alloc_free(page_ptr, s);
    }
}

#[cfg(test)]
mod tests {
    use super::super::fixture;
    use super::*;
    use crate::page::Capacity;
    use crate::snapshot::io::Reader as _;

    fn test_implicit_fixture() -> Vec<u8> {
        fixture::parse(include_str!("testdata/hyperlink-implicit-v1.hex"))
    }
    fn test_explicit_fixture() -> Vec<u8> {
        fixture::parse(include_str!("testdata/hyperlink-explicit-v1.hex"))
    }

    // test "golden implicit encoding"
    #[test]
    fn golden_implicit_encoding() {
        let test_implicit_fixture = test_implicit_fixture();

        let value = terminal_hyperlink::Hyperlink {
            id: terminal_hyperlink::HyperlinkId::Implicit(0x01020304),
            uri: b"uri".to_vec(),
        };

        let mut buf = [0u8; 128];
        let mut writer = io::FixedWriter::new(&mut buf);
        encode(&value, &mut writer).unwrap();

        fixture::expect_equal(
            fixture::Kind::Bytes,
            "src/snapshot/testdata/hyperlink-implicit-v1.hex",
            "snapshot_fixture-hyperlink-implicit-v1.hex",
            &test_implicit_fixture,
            writer.buffered(),
        );

        let mut reader = io::FixedReader::new(&test_implicit_fixture);
        let decoded = decode(&mut reader).unwrap();
        // try std.testing.expectEqualDeep(value, decoded);
        match &decoded.id {
            terminal_hyperlink::HyperlinkId::Implicit(id) => assert_eq!(0x01020304u32, *id),
            terminal_hyperlink::HyperlinkId::Explicit(_) => panic!("expected implicit id"),
        }
        assert_eq!(value.uri, decoded.uri);
        decoded.deinit();
    }

    // test "golden explicit encoding"
    #[test]
    fn golden_explicit_encoding() {
        let test_explicit_fixture = test_explicit_fixture();

        let value = terminal_hyperlink::Hyperlink {
            id: terminal_hyperlink::HyperlinkId::Explicit(b"id".to_vec()),
            uri: b"uri".to_vec(),
        };

        let mut buf = [0u8; 128];
        let mut writer = io::FixedWriter::new(&mut buf);
        encode(&value, &mut writer).unwrap();

        fixture::expect_equal(
            fixture::Kind::Bytes,
            "src/snapshot/testdata/hyperlink-explicit-v1.hex",
            "snapshot_fixture-hyperlink-explicit-v1.hex",
            &test_explicit_fixture,
            writer.buffered(),
        );

        let mut reader = io::FixedReader::new(&test_explicit_fixture);
        let decoded = decode(&mut reader).unwrap();
        // try std.testing.expectEqualDeep(value, decoded);
        match &decoded.id {
            terminal_hyperlink::HyperlinkId::Explicit(id) => assert_eq!(b"id".to_vec(), *id),
            terminal_hyperlink::HyperlinkId::Implicit(_) => panic!("expected explicit id"),
        }
        assert_eq!(value.uri, decoded.uri);
        decoded.deinit();
    }

    // test "encode rejects invalid strings before writing"
    #[test]
    fn encode_rejects_invalid_strings_before_writing() {
        struct Case {
            value: terminal_hyperlink::Hyperlink,
            expected: EncodeError,
        }
        let cases = [
            Case {
                value: terminal_hyperlink::Hyperlink {
                    id: terminal_hyperlink::HyperlinkId::Implicit(1),
                    uri: b"".to_vec(),
                },
                expected: EncodeError::InvalidUri,
            },
            Case {
                value: terminal_hyperlink::Hyperlink {
                    id: terminal_hyperlink::HyperlinkId::Explicit(b"".to_vec()),
                    uri: b"uri".to_vec(),
                },
                expected: EncodeError::InvalidExplicitId,
            },
            Case {
                value: terminal_hyperlink::Hyperlink {
                    id: terminal_hyperlink::HyperlinkId::Explicit(b"id".to_vec()),
                    uri: b"".to_vec(),
                },
                expected: EncodeError::InvalidUri,
            },
        ];

        for case in &cases {
            let mut encoded = [0u8; 32];
            let mut writer = io::FixedWriter::new(&mut encoded);
            assert_eq!(Err(case.expected), encode(&case.value, &mut writer));
            assert_eq!(0usize, writer.end);
        }
    }

    // test "decode rejects empty strings"
    #[test]
    fn decode_rejects_empty_strings() {
        struct Case {
            fixture: &'static [u8],
            expected: DecodeError,
        }
        let cases = [
            Case {
                fixture: b"\x01\x04\x03\x02\x01\x00\x00\x00\x00",
                expected: DecodeError::InvalidUri,
            },
            Case {
                fixture: b"\x02\x00\x00\x00\x00",
                expected: DecodeError::InvalidExplicitId,
            },
            Case {
                fixture: b"\x02\x02\x00\x00\x00id\x00\x00\x00\x00",
                expected: DecodeError::InvalidUri,
            },
        ];

        // PORT NOTE: `std.testing.expectError` compares only the error value;
        // the base `Hyperlink` deliberately has no `PartialEq`/`Debug`, so
        // these asserts discard the unused Ok payload with `.map(|_| ())`
        // before the exact-error comparison (the crate's
        // no-`Debug`/`PartialEq`-Ok pattern, see pagelist/tests.rs).
        for case in &cases {
            let mut reader = io::FixedReader::new(case.fixture);
            assert_eq!(Err(case.expected), decode(&mut reader).map(|_| ()));
        }
    }

    // test "decodePage ignores empty strings"
    #[test]
    fn decode_page_ignores_empty_strings() {
        let fixtures: [&[u8]; 3] = [
            b"\x01\x04\x03\x02\x01\x00\x00\x00\x00",
            b"\x02\x00\x00\x00\x00\x03\x00\x00\x00uri",
            b"\x02\x02\x00\x00\x00id\x00\x00\x00\x00",
        ];

        for fixture_bytes in fixtures {
            let mut page = Page::init(Capacity {
                cols: 1,
                rows: 1,
                hyperlink_bytes: 512,
                string_bytes: 16,
                ..Capacity::new(1, 1)
            })
            .unwrap();
            // defer page.deinit();

            let mut reader = io::FixedReader::new(fixture_bytes);
            assert_eq!(
                0 as terminal_hyperlink::Id,
                decode_page(&mut page, &mut reader).unwrap(),
            );
            assert_eq!(0usize, page.hyperlink_set.count());
            assert_eq!(Err(io::ReadError::EndOfStream), reader.take_byte());
            page.deinit();
        }
    }

    // test "decode rejects invalid kinds"
    #[test]
    fn decode_rejects_invalid_kinds() {
        for kind in [0u8, 3, u8::MAX] {
            let fixture_bytes = [kind];
            let mut reader = io::FixedReader::new(&fixture_bytes);
            assert_eq!(
                Err(DecodeError::InvalidKind),
                decode(&mut reader).map(|_| ()),
            );
        }
    }

    // test "decode allocation failure"
    //
    // PORT NOTE: `std.testing.FailingAllocator` with `fail_index` → the
    // SNAPSHOT_TW tripwire seam (`error_after(min = fail_index)`), the
    // crate's established failure-injection stand-in. Tripwires only arm in
    // debug builds, hence the cfg guard.
    #[cfg(debug_assertions)]
    #[test]
    fn decode_allocation_failure() {
        use crate::snapshot::tw;

        {
            let test_implicit_fixture = test_implicit_fixture();
            let mut reader = io::FixedReader::new(&test_implicit_fixture);
            tw::error_always(tw::SnapshotFp::Alloc);
            assert_eq!(
                Err(DecodeError::OutOfMemory),
                decode(&mut reader).map(|_| ()),
            );
            tw::end(rustty_util::tripwire::ResetMode::Reset).unwrap();
        }

        for fail_index in 0..2usize {
            let test_explicit_fixture = test_explicit_fixture();
            let mut reader = io::FixedReader::new(&test_explicit_fixture);
            tw::error_after(tw::SnapshotFp::Alloc, fail_index);
            assert_eq!(
                Err(DecodeError::OutOfMemory),
                decode(&mut reader).map(|_| ()),
            );
            tw::end(rustty_util::tripwire::ResetMode::Reset).unwrap();
        }
    }

    // test "reject every truncation"
    #[test]
    fn reject_every_truncation() {
        let fixtures = [test_implicit_fixture(), test_explicit_fixture()];

        for fixture_bytes in &fixtures {
            for fixture_len in 0..fixture_bytes.len() {
                let mut reader = io::FixedReader::new(&fixture_bytes[..fixture_len]);
                assert_eq!(
                    Err(DecodeError::EndOfStream),
                    decode(&mut reader).map(|_| ()),
                );
            }
        }
    }
}
